<script setup lang="ts">
import RecordPagination from '../components/RecordPagination.vue'
const dataSize = ref(12), batchSize = ref(20), rowSize = ref(20)
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessageBox,ElMessage} from 'element-plus'
import * as api from '../api/delivery'
import type {ImportBatch,ImportRow} from '../api/delivery'
import * as datasets from '../api/workbench'
import type {Dataset,Detail} from '../api/workbench'
import {versionName} from '../workbench-guidance'
import {session} from '../session'
const route=useRoute(),admin=computed(()=>session.user?.role==='ADMIN'),datasetId=ref(String(route.query.dataset??'')),versionId=ref(String(route.query.version??'')),q=ref(''),items=ref<Dataset[]>([]),dataPage=ref(1),dataTotal=ref(0),detail=ref<Detail>(),batches=ref<ImportBatch[]>([]),page=ref(1),total=ref(0),generation=ref(''),error=ref(''),busy=ref(false),selected=ref<ImportBatch>(),rows=ref<ImportRow[]>([]),rowPage=ref(1),rowTotal=ref(0)
const activeTab=ref(route.query.version?'new':'records')
const cleanVersions=computed(()=>detail.value?.versions.filter(v=>v.stage==='CLEAN'&&v.status==='READY')??[])
let timer:ReturnType<typeof setInterval>|undefined,alive=true,refreshing=false
async function loadData(){const result=await datasets.datasets(dataPage.value,q.value,false,dataSize.value);items.value=result.items.filter(d=>d.kind==='NEWS');dataTotal.value=result.total}
async function chooseData(){detail.value=await datasets.dataset(datasetId.value);if(!cleanVersions.value.some(v=>v.versionId===versionId.value))versionId.value=cleanVersions.value[0]?.versionId??''}
async function load(){if(refreshing)return;refreshing=true;try{const value=await api.imports(page.value,batchSize.value);if(alive){batches.value=value.items;total.value=value.total;generation.value=value.activeGenerationId;if(selected.value){selected.value=value.items.find(b=>b.id===selected.value!.id)??selected.value;await loadRows()}}}catch(v){if(alive)error.value=v instanceof Error?v.message:'读取入库记录失败'}finally{refreshing=false}}
async function loadRows(){if(!selected.value)return;const id=selected.value.id,result=await api.importRows(id,rowPage.value,rowSize.value);if(alive&&selected.value?.id===id){rows.value=result.items;rowTotal.value=result.total}}
async function perform(task:()=>Promise<void>){busy.value=true;error.value='';try{await task()}catch(v){error.value=v instanceof Error?v.message:'操作未完成'}finally{busy.value=false}}
async function start(){try{await ElMessageBox.confirm(admin.value?'将所选清洗新闻批量加入校内共享参考库？':'提交所选清洗新闻的入库申请，等待管理员批准？','批量参考入库',{confirmButtonText:admin.value?'确认入库':'提交申请',cancelButtonText:'取消'})}catch{return}await perform(async()=>{if(!datasetId.value||!versionId.value)throw new Error('请选择新闻数据集及清洗版本');await api.createImport(datasetId.value,versionId.value);ElMessage.success(admin.value?'入库任务已创建':'入库申请已提交');activeTab.value='records';await load()})}
async function action(row:ImportBatch,value:string){if(value==='APPROVE'){try{await ElMessageBox.confirm(`批准“${row.name}”进入校内共享参考库？`,'批准入库',{confirmButtonText:'批准',cancelButtonText:'取消'})}catch{return}}await perform(async()=>{await api.importAction(row.id,value);await load()})}
function view(row:ImportBatch){selected.value=row;rowPage.value=1;void perform(loadRows)}
onMounted(()=>{void perform(async()=>{await loadData();if(datasetId.value)await chooseData();await load()});timer=setInterval(()=>void load(),3000)});onBeforeUnmount(()=>{alive=false;if(timer)clearInterval(timer)})
</script>
<template><div class="page-toolbar"><p class="muted">将清洗新闻转为审核时可追溯的历史来源。</p><el-button type="primary" @click="activeTab='new'">新建入库任务</el-button></div><el-tabs v-model="activeTab" class="workspace-tabs"><el-tab-pane label="入库记录与结果" name="records"/><el-tab-pane label="选择新闻入库" name="new"/></el-tabs><el-alert v-if="error" :title="error" type="error" :closable="false"/><section v-show="activeTab==='new'" class="panel"><div class="section-heading"><div><h2>清洗新闻批量入库</h2><span class="muted">整批准备参考作品，完成后一次切换检索索引。</span></div><RouterLink v-if="admin" to="/references">参考作品列表</RouterLink><RouterLink v-else to="/datasets">数据中心</RouterLink></div><div class="import-search"><el-input v-model="q" placeholder="搜索新闻数据集" @keyup.enter="dataPage=1;perform(loadData)"/><el-button @click="dataPage=1;perform(loadData)">搜索</el-button><RecordPagination v-model:current-page="dataPage" v-model:page-size="dataSize" :total="dataTotal" @change="perform(loadData)" /></div><el-form label-position="top"><div class="import-form"><el-form-item label="新闻数据集"><el-select v-model="datasetId" @change="perform(chooseData)"><el-option v-for="d in items" :key="d.datasetId" :value="d.datasetId" :label="d.name"/><el-option v-if="detail&&!items.some(d=>d.datasetId===detail!.datasetId)" :value="detail.datasetId" :label="detail.name"/></el-select></el-form-item><el-form-item label="清洗版本"><el-select v-model="versionId"><el-option v-for="v in cleanVersions" :key="v.versionId" :value="v.versionId" :label="versionName(v)"/></el-select></el-form-item></div></el-form><el-button type="primary" :loading="busy" :disabled="!versionId" @click="start">{{admin?'批量加入共享参考库':'申请批量入库'}}</el-button></section>
<section v-show="activeTab==='records'" class="panel"><div class="section-heading"><h2>入库记录</h2><span class="muted">当前检索版本 {{generation||'暂无'}}</span><el-button @click="load">刷新</el-button></div><el-table :data="batches" empty-text="暂无入库任务"><el-table-column prop="name" label="数据集" min-width="200"/><el-table-column label="状态" min-width="150"><template #default="{row}"><el-tag :type="row.status==='COMPLETED'?'success':row.status==='FAILED'?'danger':'info'">{{api.deliveryStates[row.status]}}</el-tag></template></el-table-column><el-table-column prop="processed" label="已处理" width="85"/><el-table-column prop="inserted" label="新作品" width="85"/><el-table-column prop="duplicates" label="重复" width="80"/><el-table-column prop="rejected" label="隔离" width="80"/><el-table-column label="操作" min-width="190"><template #default="{row}"><el-button link @click="view(row)">明细</el-button><el-button v-if="admin&&row.status==='PENDING_APPROVAL'" link :disabled="busy" @click="action(row,'APPROVE')">批准入库</el-button><el-button v-if="admin&&['FAILED','INTERRUPTED','WAITING_INDEX'].includes(row.status)" link :disabled="busy" @click="action(row,'RETRY')">继续 / 重试</el-button></template></el-table-column></el-table><RecordPagination v-model:current-page="page" v-model:page-size="batchSize" :total="total" @change="load" /></section>
<section v-if="selected && activeTab==='records'" class="panel"><h2>{{selected.name}} · 入库明细</h2><el-alert v-if="selected.error" :title="selected.error" type="error" :closable="false"/><div class="import-stats"><div v-for="[key,label] in [['processed','已处理'],['inserted','新作品'],['duplicates','重复'],['rejected','隔离']]" :key="key"><span>{{label}}</span><strong>{{selected[key as 'processed'|'inserted'|'duplicates'|'rejected']}}</strong></div></div><p v-if="selected.generationId" class="muted">本批生效索引 {{selected.generationId}} · 当前索引 {{generation}}</p><el-table :data="rows" empty-text="等待逐条结果"><el-table-column prop="rowNo" label="行号" width="80"/><el-table-column prop="sourceId" label="原稿编号" min-width="170"/><el-table-column label="结果" width="120"><template #default="{row}">{{({IMPORTED:'已准备作品',DUPLICATE:'复用已有作品',REJECTED:'已隔离'} as Record<string,string>)[row.status]}}</template></el-table-column><el-table-column prop="referenceId" label="参考作品" width="110"/><el-table-column prop="message" label="说明" min-width="200"/></el-table><RecordPagination v-model:current-page="rowPage" v-model:page-size="rowSize" :total="rowTotal" @change="perform(loadRows)" /></section></template>
<style scoped>.import-search{display:flex;align-items:center;gap:12px;margin:18px 0}.import-search>.el-input{max-width:340px}.import-search .el-pagination{margin:0}.import-form{display:grid;grid-template-columns:1fr 1fr;gap:16px}.import-form .el-select{width:100%}.import-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.import-stats>div{border:1px solid var(--line);padding:16px;background:color-mix(in srgb,var(--el-color-primary) 6%,var(--canvas))}.import-stats span{color:var(--muted);font-size:12px}.import-stats strong{display:block;font-size:29px;margin-top:10px}@media(max-width:800px){.import-form{grid-template-columns:1fr}.import-stats{grid-template-columns:1fr 1fr}.import-search{flex-wrap:wrap}}</style>
